df <- data.frame (
	a = factor( c( "bob", "alice", "bob" ) ),
	b = factor( c( "kenny", "alice", "alice" ) )
);
allLevels <- unique( c( levels( df$a ), levels( df$b ) ) )
for (c in colnames(df)) {
	df[,c] <- match( df[,c], allLevels);
	levels( df[,c] ) <- 1:(length(allLevels))
};

